-- Athena saved query (Product_B2C_Intl)
-- ID: 952f0460-c869-4558-9670-4607725dba6a
-- Name: Free Seats RTC_Pvt Funnel - Syed
-- Source: Syed Athena Saved Queries export
-- Prefer dataplatform MCP / Iceberg for runs; adjust only date params.
-- Default country: IND when applicable.

WITH RTC_SDs AS ( SELECT operator_id rtc_id, CASE WHEN operator_id = 15443 THEN 'WBSTC' WHEN operator_id = 16426 THEN 'WBTC (CTC)' WHEN operator_id = 32272 THEN 'SBSTC' WHEN operator_id = 24978 THEN 'NBSTC' ELSE 'NA' END AS rtc_name, source_location_id, destination_location_id FROM "transaction"."bus_ticket_events" WHERE 1 = 1 AND time_of_event >= TIMESTAMP '2026-05-24 18:30:00' AND time_of_event < TIMESTAMP '2026-06-07 18:30:00' AND country_code = 'IND' AND operator_id IN (15443, 16426, 32272, 24978) AND sales_channel IN ('RB:MOBILEWEB#iosapp', 'RB:MOBILEWEB#droidapp', 'WEBDIRECT', 'MOBILEWEB') AND status = 'CONFIRMED' AND event_class = 2 AND event_type = 101 GROUP BY 1, 2, 3, 4 ), srp_deduped AS ( SELECT DISTINCT s.mri_session_id, s.route_id, s.os, s.channel, s.user_type, src_id, dest_id, CAST(DATE_TRUNC('day', at_timezone(s.__time, 'Asia/Kolkata')) AS DATE) AS doi, CASE WHEN operator_id IN (15443, 16426, 32272, 24978) OR op_id IN (15443, 16426, 32272, 24978) THEN 'RTC' ELSE 'Pvt' END AS rtc_pvt FROM "user_interaction"."search_route_details" s -- JOIN piligrim_dest_list p ON p.dest_id = s.dest_id WHERE s.__time >= TIMESTAMP '2026-05-24 18:30:00' AND s.__time < TIMESTAMP '2026-06-07 18:30:00' AND s.country = 'IND' AND channel_exp_info IS NOT NULL AND s.channel IN ('MOBILE_APP', 'MOBILE_WEB', 'WEB_DIRECT') -- AND s.os NOT IN ('iOS') -- AND s.channel IN ('MOBILE_WEB', 'WEB_DIRECT') AND akamai_bot IS NULL AND tp_channel = 'INVALID' -- AND CAST(src_id AS VARCHAR) || '-' || CAST(dest_id AS VARCHAR) IN ('462-122', '462-124', '462-130', '462-210', '462-222', '462-237', '462-255', '462-309', '462-311', '462-313', '462-362', '462-445', '462-450', '462-472', '462-473', '462-530', '462-545', '462-551', '462-571', '462-572', '462-574', '462-575', '462-579', '462-580', '462-624', '462-641', '462-646', '462-647', '462-750', '462-792', '462-979', '462-1003', '462-1007', '462-1008', '462-1021', '462-1142', '462-1476', '462-1571', '462-1588', '462-65976', '462-71255', '462-76079', '462-83409', '462-86833', '462-95083', '462-95217', '462-95220', '462-95222') ), sl_deduped AS ( SELECT mri_session_id, route_id FROM "user_interaction"."seat_layout_details" WHERE __time >= TIMESTAMP '2026-05-24 18:30:00' AND __time < TIMESTAMP '2026-06-07 18:30:00' AND country = 'IND' GROUP BY 1,2 ), mpax_deduped AS ( SELECT mri_session_id, route_id FROM "user_interaction"."cust_info_details" WHERE __time >= TIMESTAMP '2026-05-24 18:30:00' AND __time < TIMESTAMP '2026-06-07 18:30:00' AND country = 'IND' GROUP BY 1,2 ), orderinfo_deduped AS ( SELECT mri_session_id, route_id, MAX(rb_user_id) as rb_user_id FROM "user_interaction"."order_info_details" WHERE __time >= TIMESTAMP '2026-05-24 18:30:00' AND __time < TIMESTAMP '2026-06-07 18:30:00' -- AND os = 'Android' AND country = 'IND' GROUP BY 1,2 ), confirm_deduped AS ( SELECT mri_session_id, route_id, COUNT(DISTINCT tin) as tin_count FROM "user_interaction"."confirm_order_details" WHERE __time >= TIMESTAMP '2026-05-24 18:30:00' AND __time < TIMESTAMP '2026-06-07 18:30:00' AND country = 'IND' AND status = 200 AND tin IS NOT NULL AND tin NOT IN ('', 'null') GROUP BY 1,2 ) SELECT -- srp.month_period || CASE WHEN srp.doi >= DATE '2026-05-25' AND srp.doi <= DATE '2026-05-31' THEN 'Before Free Seats' WHEN srp.doi >= DATE '2026-06-01' AND srp.doi <= DATE '2026-06-07' THEN 'After Free Seats' END AS time_period, r.rtc_id, r.rtc_name, srp.user_type, CASE WHEN srp.channel = 'MOBILE_APP' THEN srp.os ELSE srp.channel END AS channel, rtc_pvt, -- 'Overall' AS rtc_pvt, COUNT(DISTINCT srp.mri_session_id) AS srpload, COUNT(DISTINCT sl.mri_session_id) AS slload, COUNT(DISTINCT pax.mri_session_id) AS CustInfoload, COUNT(DISTINCT oi.mri_session_id) AS paymentload, COUNT(DISTINCT conf.mri_session_id) AS confirmsession, SUM(conf.tin_count) AS tin FROM srp_deduped srp INNER JOIN RTC_SDs r ON r.source_location_id = srp.src_id AND r.destination_location_id = srp.dest_id LEFT JOIN sl_deduped sl ON srp.mri_session_id = sl.mri_session_id AND srp.route_id = sl.route_id LEFT JOIN mpax_deduped pax ON srp.mri_session_id = pax.mri_session_id AND srp.route_id = pax.route_id LEFT JOIN orderinfo_deduped oi ON srp.mri_session_id = oi.mri_session_id AND srp.route_id = oi.route_id LEFT JOIN confirm_deduped conf ON srp.mri_session_id = conf.mri_session_id AND srp.route_id = conf.route_id WHERE 1 = 1 GROUP BY 1, 2 , 3, 4 , 5, 6 ORDER BY 2, 3, 4 DESC, 5 DESC
